fn countRows(s: []const u8) usize {
    var count: usize = 0;
    var i: usize = 0;
    while (i < s.len) {
        // start of line
        var line_start = i;
        while (i < s.len and s[i] != '\n') i += 1;
        const line = s[line_start..i];
        // check if line has non-whitespace
        var has = false;
        for (line) |c| {
            if (!isWhitespace(c)) { has = true; break; }
        }
        if (has) count += 1;
        if (i < s.len) i += 1; // skip newline
    }
    return count;
}
```

