fn parseNumber(token: []const u8) !i16 {
    if (token.len == 0) return error.InvalidCharacter;
    var negative = false;
    var i: usize = 0;
    if (token[0] == '-') {
        negative = true;
        i = 1;
    } else if (token[0] == '+') {
        i = 1;
    }
    var value: i32 = 0;
    var has_digit = false;
    while (i < token.len) {
        const c = token[i];
        if (c < '0' or c > '9') return error.InvalidCharacter;
        value = value * 10 + @as(i32, @intCast(c - '0'));
        has_digit = true;
        i += 1;
    }
    if (!has_digit) return error.InvalidCharacter;
    const signed_value: i32 = if (negative) -value else value;
    if (signed_value > 32767 or signed_value < -32768) return error.Overflow;
    return @intCast(signed_value);
}
